\begin{pmatrix}\label{matrix} 
a & b \\
c & d
\end{pmatrix} \subset {\mathrm{M}}_2(\widehat{{\cal O}_K}) ~|~ c \equiv 0 ~{\mathrm{mod}}~ N
\Bigg\}.
